export type SlashToken = {
	/** 词元文本（含 / 前缀，不含空白） */
	text: string;
	/** 在原字符串中的区间 [start, end) */
	start: number;
	end: number;
};

/**
 * 光标所在位置的 slash 词元：以 / 开头、且 / 前是行首或空白的连续非空白串。
 * 用于「消息中途输入 /」时也能唤起命令/技能弹层；URL（https://…）、路径（src/foo）
 * 中的 / 因前一个字符非空白而不会误触发。
 */
export function slashTokenAt(value: string, caret: number): SlashToken | null {
	const text = value ?? '';
	if (!Number.isFinite(caret) || caret < 0 || caret > text.length) {
		return null;
	}
	const m = /(?:^|\s)(\/[^\s]*)$/.exec(text.slice(0, caret));
	if (!m) {
		return null;
	}
	const start = caret - m[1]!.length;
	let end = caret;
	while (end < text.length && !/\s/.test(text[end]!)) {
		end += 1;
	}
	return {text: text.slice(start, end), start, end};
}

